// JSON 解析和比对 Worker
self.onmessage = function(e) {
  const { action, json, json1, json2 } = e.data
  
  try {
    if (action === 'parse') {
      const parsed = JSON.parse(json)
      self.postMessage({
        success: true,
        data: parsed
      })
    } else if (action === 'compare') {
      const obj1 = JSON.parse(json1)
      const obj2 = JSON.parse(json2)
      const result = findDifferences(obj1, obj2)
      self.postMessage({
        success: true,
        data: result
      })
    }
  } catch (error) {
    self.postMessage({
      success: false,
      error: error
    })
  }
}

function findDifferences(obj1, obj2, path = '') {
  const result = {}
  
  // 获取所有键
  const allKeys = new Set([...Object.keys(obj1), ...Object.keys(obj2)])
  
  for (const key of allKeys) {
    const currentPath = path ? `${path}.${key}` : key
    
    if (!(key in obj1)) {
      result[key] = { 
        type: '第一个json中缺少该字段',
        first: '空',
        second: obj2[key]
      }
    } else if (!(key in obj2)) {
      result[key] = { 
        type: '第二个json中缺少该字段',
        first: obj1[key],
        second: '空'
      }
    } else if (JSON.stringify(obj1[key]) !== JSON.stringify(obj2[key])) {
      if (typeof obj1[key] === 'object' && obj1[key] !== null &&
          typeof obj2[key] === 'object' && obj2[key] !== null) {
        result[key] = findDifferences(obj1[key], obj2[key], currentPath)
      } else {
        result[key] = {
          type: '不一致',
          first: obj1[key],
          second: obj2[key]
        }
      }
    }
  }
  
  return result
} 